<script>
  const log = [];
  document.addEventListener("dragstart", e => {
    log.push("dragstart target=" + e.target.id + " tag=" + e.target.tagName);
    e.target.classList.add("dim");
    e.dataTransfer.setData("text/plain", e.target.id);
    e.dataTransfer.effectAllowed = "move";
  });
  document.querySelectorAll(".col").forEach(col => {
    col.addEventListener("dragover", e => { e.preventDefault(); col.classList.add("hover"); });
    col.addEventListener("dragleave", e => col.classList.remove("hover"));
    col.addEventListener("drop", e => {
      e.preventDefault();
      const id = e.dataTransfer.getData("text/plain");
      const card = document.getElementById(id);
      col.appendChild(card);
      log.push("dropped " + id + " on " + col.id);
    });
  });
  document.addEventListener("dragend", e => {
    e.target.classList.remove("dim");
    log.push("dragend");
    document.getElementById("log").textContent = log.join("\n");
  });
</script>
<pre id="log"></pre>
</body>
</html>
